{
  "name": "taxating/taxation",
  "description": "Standalone Symfony runtime harness and component package for Smart Responsor Taxating/Taxation workflows.",
  "type": "library",
  "license": "proprietary",
  "autoload": {
    "psr-4": {
      "App\\Taxating\\": "src/"
    }
  },
  "autoload-dev": {
    "psr-4": {
      "Tests\\": "tests/"
    }
  },
  "require": {
    "php": "^8.4",
    "promphp/prometheus_client_php": "^2.10",
    "symfony/config": "^8.1",
    "symfony/console": "^8.1",
    "symfony/dependency-injection": "^8.1",
    "symfony/form": "^8.1",
    "symfony/http-foundation": "^8.1",
    "symfony/http-kernel": "^8.1",
    "symfony/yaml": "^8.1",
    "ext-yaml": "*",
    "ext-curl": "*",
    "ext-zip": "*",
    "ext-openssl": "*",
    "ext-pdo": "*",
    "ext-redis": "*",
    "ext-simplexml": "*",
    "google/apiclient": "^2.19",
    "nelmio/api-doc-bundle": "^5.10",
    "symfony/asset": "^8.1",
    "symfony/twig-bundle": "^8.1",
    "symfony/serializer": "^8.1",
    "symfony/runtime": "^8.1",
    "symfony/framework-bundle": "^8.1",
    "symfony/dotenv": "^8.1",
    "doctrine/dbal": "^4.0",
    "doctrine/orm": "^3.3",
    "doctrine/doctrine-bundle": "^3.0",
    "symfony/security-bundle": "^8.1",
    "symfony/monolog-bundle": "^4.0",
    "objecting/object": "*@dev",
    "cruding/crud": "*@dev",
    "collectioning/collection": "*@dev",
    "tabling/table": "*@dev",
    "viewing/view": "*@dev",
    "interfacing/interface": "*@dev",
    "easycorp/easyadmin-bundle": "^5.0",
    "doctrine/doctrine-migrations-bundle": "4.0",
    "symfony/validator": "8.1"
  },
  "require-dev": {
    "phpunit/phpunit": "^10.0",
    "phpstan/phpstan": "^2.2",
    "friendsofphp/php-cs-fixer": "^3.94",
    "fakerphp/faker": "*",
    "doctrine/data-fixtures": "*"
  },
  "scripts": {
    "test": "vendor/bin/phpunit --configuration phpunit.xml.dist --colors=always",
    "phpstan": "phpstan analyse --configuration=phpstan.neon --no-progress",
    "phpstan:max": "phpstan analyse --configuration=phpstan.neon --level=max --no-progress",
    "fix": "php -d memory_limit=1G vendor/bin/php-cs-fixer fix",
    "fix:check": "php -d memory_limit=1G vendor/bin/php-cs-fixer fix --dry-run --diff"
  },
  "config": {
    "allow-plugins": {
      "symfony/runtime": true
    }
  },
  "repositories": [
    {
      "type": "path",
      "url": "../Objecting",
      "options": {
        "symlink": true
      }
    },
    {
      "type": "path",
      "url": "../Cruding",
      "options": {
        "symlink": true
      }
    },
    {
      "type": "path",
      "url": "../Collectioning",
      "options": {
        "symlink": true
      }
    },
    {
      "type": "path",
      "url": "../Tabling",
      "options": {
        "symlink": true
      }
    },
    {
      "type": "path",
      "url": "../Viewing",
      "options": {
        "symlink": true
      }
    },
    {
      "type": "path",
      "url": "../Interfacing",
      "options": {
        "symlink": true
      }
    }
  ]
}
